/**
 * Ownership is per field, not per system: the ERP owns price and stock,
 * the storefront owns description and images. Comparing everything produces
 * noise; comparing what each side owns produces signal.
 */
const OWNED_BY_ERP = ['priceMinor', 'stockOnHand', 'taxClass'] as const;

export async function reconcileProducts(): Promise<ReconcileReport> {
  const report: ReconcileReport = { checked: 0, repaired: [], escalated: [] };

  for await (const batch of erp.streamProducts({ pageSize: 500 })) {
    const storefront = await store.getProducts(batch.map((p) => p.sku));

    for (const product of batch) {
      report.checked++;
      const mirror = storefront.get(product.sku);

      if (!mirror) {
        report.escalated.push({ sku: product.sku, reason: 'missing_in_store' });
        continue;
      }

      const drifted = OWNED_BY_ERP.filter((f) => product[f] !== mirror[f]);
      if (drifted.length === 0) continue;

      // Safe to repair: the ERP owns these fields, so it wins by definition.
      await store.updateProduct(product.sku, pick(product, drifted));
      report.repaired.push({ sku: product.sku, fields: drifted });
    }
  }

  // A silent reconciliation job is one nobody notices has stopped running.
  await metrics.gauge('reconcile.drift', report.repaired.length);
  return report;
}
